/** The example workspace directory, path → text: one resource of each kind and a workflow using them. */
export const WORKSPACE_COOKBOOK: Readonly<Record<string, string>> = {"credentials.ts":"// @sim-sdk 1\nimport { defineCredentials } from \u0027@sim/workflow-sdk/workspace\u0027\n\n// credentials.ts: the saved credentials workflows use as credential(\u0027<key>\u0027), by provider only.\n// An apply binds each key to this workspace\u0027s credential of that provider.\nexport default defineCredentials({\n  slack: { provider: \u0027slack\u0027 },\n})\n","deployments/support.ts":"// @sim-sdk 1\nimport { defineDeployment } from \u0027@sim/workflow-sdk/workspace\u0027\n\n// deployments/<workflow key>.ts deploys workflows/<workflow key>/ after the apply writes it.\n// \u0027draft\u0027 publishes the draft whenever it differs from the live version; \u0027pinned\u0027 never does.\nexport default defineDeployment({\n  live: \u0027draft\u0027,\n  api: { public: false },\n  chat: {\n    identifier: \u0027support-example\u0027,\n    title: \u0027Support\u0027,\n    // A password is a secret by name, never its value: auth: { password: env.CHAT_PASSWORD }.\n    auth: { emails: [\u0027@example.com\u0027] },\n    outputs: [{ block: \u0027Answer\u0027, path: \u0027content\u0027 }],\n  },\n})\n","files/templates/reply.md":"Hi {{name}},\n\nThanks for reaching out about order {{orderId}}.\n","knowledge/policies/docs/refunds.md":"# Refunds\n\nOrders can be refunded within 30 days of delivery. Refunds go back to the original payment method.\n","knowledge/policies/knowledge.ts":"// @sim-sdk 1\nimport { defineKnowledgeBase } from \u0027@sim/workflow-sdk/workspace\u0027\n\n// knowledge/<key>/knowledge.ts, with one file per document in knowledge/<key>/docs/ (flat, each\n// at most 10 MB). A workflow names it as knowledgeBase(\u0027policies\u0027).\nexport default defineKnowledgeBase({\n  name: \u0027Policies\u0027,\n  description: \u0027Refund and shipping policies\u0027,\n  chunking: { maxSize: 1024, minSize: 100, overlap: 200 },\n})\n","mcp/docs.ts":"// @sim-sdk 1\nimport { defineMcpServer, env } from \u0027@sim/workflow-sdk/workspace\u0027\n\n// mcp/<key>.ts: an MCP server the workspace\u0027s agents call tools on. A workflow names it by key\n// and a tool by name: mcp(\u0027docs\u0027).tool(\u0027search_docs\u0027). A credential header holds an env reference,\n// never the secret itself; `stored()` keeps the value the server already holds. The server\u0027s id\n// derives from its URL, so changing `url` replaces the server.\nexport default defineMcpServer({\n  name: \u0027Docs\u0027,\n  url: \u0027https://docs.example.com/mcp\u0027,\n  headers: { Authorization: \u0027Bearer {{DOCS_MCP_TOKEN}}\u0027, \u0027X-Api-Key\u0027: env.DOCS_MCP_KEY },\n  timeout: 10000,\n})\n","secrets.ts":"// @sim-sdk 1\nimport { defineSecrets } from \u0027@sim/workflow-sdk/workspace\u0027\n\n// secrets.ts: the workspace secrets workflows read as env.NAME, by name and description only.\n// A value never appears here: set one with `sim secrets set NAME --scope workspace`.\nexport default defineSecrets({\n  ANTHROPIC_API_KEY: { description: \u0027Model access for the support agent\u0027 },\n  DOCS_MCP_KEY: { description: \u0027API key the docs MCP server checks\u0027 },\n  DOCS_MCP_TOKEN: { description: \u0027Bearer token for the docs MCP server\u0027 },\n})\n","skills/tone.md":"---\nname: tone\ndescription: \"Answer in the support team\u0027s voice: short, warm, specific.\"\n---\nWrite like a person, not a policy. Lead with the answer, then the one detail that matters.\n","tables/orders.ts":"// @sim-sdk 1\nimport { column, defineTable } from \u0027@sim/workflow-sdk/workspace\u0027\n\n// tables/<key>.ts: the key (`orders`) is how a workflow names it: table(\u0027orders\u0027). Rows are\n// never part of source. To rename a column keep its key and set `name`.\nexport default defineTable({\n  name: \u0027orders\u0027,\n  description: \u0027Order questions the support workflow answered\u0027,\n  columns: {\n    orderId: column.string({ required: true }),\n    status: column.select({ options: [\u0027open\u0027, \u0027answered\u0027] }),\n    total: column.number(),\n  },\n})\n","tools/lookup-order.js":"// Each schema parameter is a variable; $env.NAME reads an environment variable by name, so the\n// value never appears in source.\nconst response = await fetch(`https://orders.example.com/api/orders/${encodeURIComponent(orderId)}`, {\n  headers: { Authorization: `Bearer ${$env.ORDERS_API_KEY}` },\n})\nreturn await response.json()\n","tools/lookup-order.ts":"// @sim-sdk 1\nimport { codeFile, defineTool } from \u0027@sim/workflow-sdk/workspace\u0027\n\n// tools/<key>.ts, with its code in tools/<key>.js.\n// A workflow names it as customTool(\u0027lookup-order\u0027).\nexport default defineTool({\n  title: \u0027Lookup order\u0027,\n  schema: {\n    type: \u0027function\u0027,\n    function: {\n      name: \u0027lookup_order\u0027,\n      description: \u0027Find an order by id.\u0027,\n      parameters: {\n        type: \u0027object\u0027,\n        properties: { orderId: { type: \u0027string\u0027 } },\n        required: [\u0027orderId\u0027],\n      },\n    },\n  },\n  code: codeFile(\u0027./lookup-order.js\u0027),\n})\n","workflows/support/workflow.ts":"// @sim-sdk 1\nimport {\n  agent,\n  customTool,\n  env,\n  knowledge,\n  knowledgeBase,\n  skill,\n  t,\n  table,\n  trigger,\n  workflow,\n} from \u0027@sim/workflow-sdk\u0027\n\n// workflows/<key>/workflow.ts: a workflow source directory. It names the resources this\n// directory declares by key, and one apply creates them before the workflow that uses them.\nexport default workflow(\u0027Support\u0027, { description: \u0027Answers an order question.\u0027 }, () => {\n  const start = trigger.start(\u0027Start\u0027, { inputFormat: { orderId: \u0027string\u0027, question: \u0027string\u0027 } })\n  const policy = knowledge.search(\u0027Policy Search\u0027, {\n    knowledgeBaseId: knowledgeBase(\u0027policies\u0027),\n    query: start.question,\n    topK: 3,\n  })\n  const answer = agent(\u0027Answer\u0027, {\n    model: \u0027claude-sonnet-4-6\u0027,\n    // An environment variable by name; its value never appears in source.\n    apiKey: env.ANTHROPIC_API_KEY,\n    messages: [\n      { role: \u0027system\u0027, content: t`Answer from these policies:\\n${policy.results}` },\n      { role: \u0027user\u0027, content: t`Order ${start.orderId}: ${start.question}` },\n    ],\n    tools: [customTool(\u0027lookup-order\u0027)],\n    skills: [skill(\u0027tone\u0027)],\n  })\n  const log = table.insertRow(\u0027Log Question\u0027, {\n    tableId: table(\u0027orders\u0027),\n    data: { orderId: start.orderId, status: \u0027answered\u0027 },\n  })\n\n  start.to(policy)\n  policy.to(answer)\n  answer.to(log)\n})\n"}
